import Foundation

/// One downloadable file, as listed by content/manifest.json (generated by the Android repo's tools/sync-content.mjs).
struct ContentFile: Codable, Equatable, Hashable {
    let path: String
    let bytes: Int64
    let pack: String
}

/// The list of every downloadable file with its size and pack; bundled as `Content/manifest.json`.
struct Manifest: Codable, Equatable {
    var generated: String = ""
    var files: [ContentFile] = []

    private var index: [String: ContentFile] { Dictionary(files.map { ($0.path, $0) }, uniquingKeysWith: { a, _ in a }) }

    var totalBytes: Int64 { files.reduce(0) { $0 + $1.bytes } }

    func bytesOf(_ packs: Set<String>) -> Int64 { files.filter { packs.contains($0.pack) }.reduce(0) { $0 + $1.bytes } }

    /// The files a mode downloads up front: everything, the essential packs, or nothing.
    func filesFor(_ mode: ContentMode) -> [ContentFile] {
        switch mode {
        case .todo: return files
        case .esencial: return files.filter { Packs.essential.contains($0.pack) }
        case .uso, .enLinea: return []
        }
    }

    func byPath(_ path: String) -> ContentFile? { files.first { $0.path == path } }

    static func parse(_ data: Data) throws -> Manifest { try AppJson.decode(Manifest.self, data) }
}

/// The four choices of the first open (pref `contenido.modo`).
enum ContentMode: String, CaseIterable {
    case todo, esencial, uso, enLinea = "en-linea"

    var value: String { rawValue }
    var label: String {
        switch self {
        case .todo: return "Descargar todo"
        case .esencial: return "Descargar lo esencial"
        case .uso: return "Solo lo que uso"
        case .enLinea: return "Mantener solo en línea"
        }
    }
    /// Downloads packs up front.
    var downloads: Bool { self == .todo || self == .esencial }
    /// Keeps what it reads on disk.
    var persists: Bool { self != .enLinea }

    static func of(_ value: String?) -> ContentMode? { value.flatMap { ContentMode(rawValue: $0) } }
}

/// The packs the manifest groups files into, in display order.
enum Packs {
    static let order = ["himnario-es", "himnario-pt", "biblia", "escuela", "buscar", "egw"]
    static let essential: Set<String> = ["himnario-es", "biblia", "escuela", "buscar"]

    static func label(_ id: String) -> String {
        switch id {
        case "himnario-es": return "Himnario Adventista"
        case "himnario-pt": return "Hinários (portugués)"
        case "biblia": return "Biblia Reina-Valera 1960"
        case "escuela": return "Escuela Sabática y Quiz"
        case "buscar": return "Índice de búsqueda"
        case "egw": return "25 libros de Ellen G. White"
        default: return id
        }
    }
}

/// «5,9 MB» under ten megabytes, «29 MB» above; decimal megabytes, Spanish comma.
func formatMb(_ bytes: Int64) -> String {
    if bytes <= 0 { return "0 MB" }
    let mb = Double(bytes) / 1_000_000
    if mb < 10 { return String(format: "%.1f", mb).replacingOccurrences(of: ".", with: ",") + " MB" }
    return "\(Int(mb.rounded())) MB"
}
